/**
 * Accessory art on the same grid, drawn over the finished sprite. '.' = transparent. Codes come from
 * the art's own [palette]; k/h/H/s/S fall back to the sprite's outline/hair/skin, so e.g. cat ears
 * match the hair. [behind] cells only show where the sprite is empty. [hideAbove] clears the
 * character's rows above that line first (a hat's brim hides the hair above it).
 */
internal class AccessoryArt(
    val palette: Map<Char, Color>,
    val front: Map<Int, String> = emptyMap(),
    val behind: Map<Int, String> = emptyMap(),
    /** Twinkle points (x, y), each lighting up in turn. */
    val sparkles: List<Pair<Int, Int>> = emptyList(),
    /** Lower [behind] rows sway sideways (capes). */
    val sway: Boolean = false,
    val hideAbove: Int = 0,
) {
    val animated get() = sparkles.isNotEmpty() || sway
}

